WITH seasonal AS (SELECT CASE WHEN strftime('%m', s.sale_date) IN ('12','01','02') THEN 'Winter' WHEN strftime('%m', s.sale_date) IN ('03','04','05') THEN 'Spring' WHEN strftime('%m', s.sale_date) IN ('06','07','08') THEN 'Summer' ELSE 'Fall' END AS season, p.category, SUM(s.quantity) AS total_quantity, SUM(s.quantity * s.price) AS total_revenue FROM sales s JOIN products p ON p.product_id = s.product_id GROUP BY season, p.category),
ranked AS (SELECT *, RANK() OVER (PARTITION BY season ORDER BY total_quantity DESC, total_revenue DESC, category ASC) AS rk FROM seasonal)
SELECT season, category, total_quantity, total_revenue FROM ranked WHERE rk = 1 ORDER BY season;

WITH recent AS (SELECT employee_id, rating, ROW_NUMBER() OVER (PARTITION BY employee_id ORDER BY review_date DESC, review_id DESC) AS rn FROM performance_reviews),
last3 AS (SELECT employee_id, MAX(CASE WHEN rn = 1 THEN rating END) AS r1, MAX(CASE WHEN rn = 2 THEN rating END) AS r2, MAX(CASE WHEN rn = 3 THEN rating END) AS r3, COUNT(*) AS cnt FROM recent WHERE rn <= 3 GROUP BY employee_id)
SELECT e.employee_id, e.name, l.r1 - l.r3 AS improvement_score FROM last3 l JOIN employees e ON e.employee_id = l.employee_id WHERE l.cnt = 3 AND l.r1 > l.r2 AND l.r2 > l.r3 ORDER BY improvement_score DESC, e.name;
